#!/bin/bash
set -euo pipefail

# Run the same tests on fresh runners, with mbx enabled for both compilers.
# The caller seeds or restores an isolated object cache before invoking this.
phase=${BENCH_PHASE:?}
case "$phase" in seed | compare) ;; *) exit 2 ;; esac
compiler=${BENCH_COMPILER:?}
case "$compiler" in
cargo) blaze=0 ;;
blaze) blaze=1 ;;
*) exit 2 ;;
esac
memory_max=${BENCH_MEMORY_MAX:-12G}
case "$memory_max" in 12G | infinity) ;; *) exit 2 ;; esac
mkdir -p build-memory-results
# Generated by the pinned installer.
# shellcheck source=/dev/null
source .blaze/env.sh
export MBX_DISABLE=0 MBX_BLAZE=$blaze
export MBX_LOG=info,mbx::cli::blaze=debug
# Downloads are outside the test measurement for both compilers.
MBX_BLAZE=0 cargo fetch --locked

unit="aube-warm-${compiler}-${GITHUB_RUN_ID:?}"
# Pass only build-tool settings, not the GitHub token or cache service tokens.
settings=()
while IFS= read -r name; do
	case "$name" in
	MBX_* | BLAZE_* | RA_JIT_* | CARGO_* | RUST* | XDG_*) settings+=("--setenv=$name=${!name}") ;;
	esac
done < <(compgen -e)
trap 'sudo systemctl stop "$unit" >/dev/null 2>&1 || true' EXIT
timeout=1500
if [[ $compiler == blaze && $phase == seed ]]; then timeout=5400; fi
started=$(date +%s)
sudo systemd-run --unit="$unit" --no-block \
	--property=Type=oneshot --property=RemainAfterExit=yes \
	--property=MemoryAccounting=yes --property="MemoryMax=$memory_max" \
	--property=LimitMEMLOCK=67108864 \
	--property="TimeoutStartSec=$timeout" \
	--working-directory="$PWD" --uid="$(id -u)" \
	--setenv="BENCH_PHASE=$phase" \
	--setenv="HOME=$HOME" --setenv="PATH=$PATH" \
	--setenv="MISE_TRUSTED_CONFIG_PATHS=$PWD" \
	"${settings[@]}" \
	bash -c 'if [ "$MBX_BLAZE" = 1 ]; then if [ "$BENCH_PHASE" = seed ]; then bash scripts/prime-blaze-cache.sh; else sh scripts/test-ci.sh; fi; else cargo test --locked --lib --bins --tests && cargo test --locked --doc; fi'
deadline=$((SECONDS + timeout + 100))
peak_anon=0
group="/sys/fs/cgroup$(sudo systemctl show "$unit" --property=ControlGroup --value)"
while :; do
	if [[ -r $group/memory.stat ]]; then
		anon=$(awk '$1 == "anon" || $1 == "shmem" { total += $2 } END { printf "%.0f", total }' "$group/memory.stat")
		if ((anon > peak_anon)); then peak_anon=$anon; fi
	fi
	state=$(sudo systemctl show "$unit" --property=SubState --value)
	case "$state" in exited | failed) break ;; esac
	if ((SECONDS >= deadline)); then exit 1; fi
	sleep 0.2
done
elapsed=$(($(date +%s) - started))
# The shell owns the output files; sudo is only needed to read systemd.
# shellcheck disable=SC2024
sudo systemctl show "$unit" -p MemoryPeak -p CPUUsageNSec -p Result \
	>build-memory-results/measurement.properties
printf 'ElapsedSeconds=%s\nSampledAnonymousPeak=%s\nCompiler=%s\nPhase=%s\n' \
	"$elapsed" "$peak_anon" "$compiler" "$BENCH_PHASE" >>build-memory-results/measurement.properties
# shellcheck disable=SC2024
sudo journalctl -u "$unit" --no-pager >build-memory-results/test.log
printf 'MemoryLimit=%s\n' "$memory_max" >>build-memory-results/measurement.properties
if [[ -f "$BLAZE_HOME/v2/serve.log" ]]; then
	cp "$BLAZE_HOME/v2/serve.log" build-memory-results/blaze-daemon.log
fi
cat build-memory-results/measurement.properties
result=$(sudo systemctl show "$unit" --property=Result --value)
[[ $result == success ]]
# Fail rather than silently report a Cargo fallback as a Blaze measurement.
if [[ $compiler == blaze ]]; then
	grep -q 'sending .*cargo test.* through .*blaze' build-memory-results/test.log
fi
